package com.yeyamo_mobile.api.culture_service.application;
import static com.yeyamo_mobile.api.culture_service.domain.CultureEnums.*;import com.yeyamo_mobile.api.culture_service.domain.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
public final class CultureDtos {private CultureDtos(){}
 public record TranslationRequest(@NotBlank String languageCode,@NotBlank String title,String summary,String body){}
 public record ProverbDetailsRequest(@NotBlank String literalTranslation,@NotBlank String meaning,@NotBlank String originLanguageCode,@Size(max=2048) String audioUrl){}
 public record RecipeIngredientRequest(UUID id,@NotBlank@Size(max=255) String name,@Size(max=80) String quantity,@Size(max=80) String unit,@Size(max=120) String groupName,Boolean optional,@Size(max=4000) String substitutionNotes,@DecimalMin("0.0") java.math.BigDecimal quantityValue,@DecimalMin("0.0") java.math.BigDecimal quantityMaxValue,QuantityUnitCode quantityUnitCode){public RecipeIngredientRequest(String name,String quantity,String unit){this(null,name,quantity,unit,null,false,null,null,null,null);}}
 public record RecipeStepRequest(UUID id,@Size(max=255) String title,@NotBlank String instruction,@Positive Integer durationMinutes,@DecimalMin("0.0") java.math.BigDecimal temperatureValue,TemperatureUnit temperatureUnit,String expectedResult,String tip,String safetyNote,UUID mediaId,List<UUID> ingredientIds){public RecipeStepRequest(String instruction){this(null,null,instruction,null,null,null,null,null,null,null,List.of());}}
 public record RecipeEquipmentRequest(UUID id,@NotBlank@Size(max=255)String name,Boolean optional){}
 public record RecipeMediaRequest(UUID id,@NotNull UUID mediaId,@NotNull RecipeMediaRole role,@Size(max=500)String caption,@Size(max=500)String altText){}
 public record RecipeDetailsRequest(@NotEmpty@Size(max=250)@Valid List<RecipeIngredientRequest> ingredients,@NotEmpty@Size(max=250)@Valid List<RecipeStepRequest> steps,@Positive Integer prepTimeMinutes,@Positive Integer servings,@Positive Integer cookTimeMinutes,@Positive Integer restTimeMinutes,RecipeDifficulty difficulty,@Size(max=255)String yieldText,UUID heroMediaId,UUID videoMediaId,@Size(max=512)String youtubeVideoUrl,String preparationAhead,String plating,String storage,String reheating,String tips,String variants,String accompaniments,String safetyNotes,@Size(max=100)@Valid List<RecipeEquipmentRequest> equipment,@Size(max=50)@Valid List<RecipeMediaRequest> gallery){public RecipeDetailsRequest(List<RecipeIngredientRequest> ingredients,List<RecipeStepRequest> steps,Integer prep,Integer servings){this(ingredients,steps,prep,servings,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,List.of(),List.of());}}
 public record ContentRequest(@NotNull ContentType type,@NotBlank String slug,@NotBlank String primaryLanguageCode,@NotBlank@Size(min=2,max=2)String countryCode,String adminLevel1Id,String adminLevel2Id,String cityId,String localityId,String communityName,@NotNull ContributorType contributorType,@NotNull SourceType sourceType,@NotNull SensitivityLevel sensitivityLevel,@NotNull Visibility visibility,@NotNull@Valid TranslationRequest translation,@Valid ProverbDetailsRequest proverbDetails,@Valid RecipeDetailsRequest recipeDetails){}
 public record ProverbDetailsResponse(String literalTranslation,String meaning,String originLanguageCode,String audioUrl){public static ProverbDetailsResponse from(ProverbDetailsEntity d){return d==null?null:new ProverbDetailsResponse(d.getLiteralTranslation(),d.getMeaning(),d.getOriginLanguage().getCode(),d.getAudioUrl());}}
 public record RecipeIngredientResponse(UUID id,String name,String quantity,String unit,String groupName,boolean optional,String substitutionNotes,java.math.BigDecimal quantityValue,java.math.BigDecimal quantityMaxValue,QuantityUnitCode quantityUnitCode){public static RecipeIngredientResponse from(RecipeDetailsEntity.RecipeIngredient i){return new RecipeIngredientResponse(i.getId(),i.getName(),i.getQuantity(),i.getUnit(),i.getGroupName(),i.isOptional(),i.getSubstitutionNotes(),i.getQuantityValue(),i.getQuantityMaxValue(),i.getQuantityUnitCode());}}
 public record RecipeStepResponse(UUID id,String title,String instruction,Integer durationMinutes,java.math.BigDecimal temperatureValue,TemperatureUnit temperatureUnit,String expectedResult,String tip,String safetyNote,UUID mediaId,List<UUID> ingredientIds){public static RecipeStepResponse from(RecipeDetailsEntity.RecipeStep s){return new RecipeStepResponse(s.getId(),s.getTitle(),s.getInstruction(),s.getDurationMinutes(),s.getTemperatureValue(),s.getTemperatureUnit(),s.getExpectedResult(),s.getTip(),s.getSafetyNote(),s.getMediaId(),s.getIngredients().stream().map(RecipeDetailsEntity.RecipeIngredient::getId).toList());}}
 public record RecipeEquipmentResponse(UUID id,String name,boolean optional){public static RecipeEquipmentResponse from(RecipeDetailsEntity.RecipeEquipment e){return new RecipeEquipmentResponse(e.getId(),e.getName(),e.isOptional());}}
 public record RecipeMediaResponse(UUID id,UUID mediaId,RecipeMediaRole role,String caption,String altText){public static RecipeMediaResponse from(RecipeDetailsEntity.RecipeMedia m){return new RecipeMediaResponse(m.getId(),m.getMediaId(),m.getRole(),m.getCaption(),m.getAltText());}}
 public record RecipeDetailsResponse(List<RecipeIngredientResponse> ingredients,List<RecipeStepResponse> steps,Integer prepTimeMinutes,Integer servings,Integer cookTimeMinutes,Integer restTimeMinutes,RecipeDifficulty difficulty,String yieldText,UUID heroMediaId,UUID videoMediaId,String youtubeVideoUrl,String preparationAhead,String plating,String storage,String reheating,String tips,String variants,String accompaniments,String safetyNotes,List<RecipeEquipmentResponse> equipment,List<RecipeMediaResponse> gallery){public static RecipeDetailsResponse from(RecipeDetailsEntity d){return d==null?null:new RecipeDetailsResponse(d.getIngredients().stream().map(RecipeIngredientResponse::from).toList(),d.getSteps().stream().map(RecipeStepResponse::from).toList(),d.getPrepTimeMinutes(),d.getServings(),d.getCookTimeMinutes(),d.getRestTimeMinutes(),d.getDifficulty(),d.getYieldText(),d.getHeroMediaId(),d.getVideoMediaId(),d.getYoutubeVideoUrl(),d.getPreparationAhead(),d.getPlating(),d.getStorage(),d.getReheating(),d.getTips(),d.getVariants(),d.getAccompaniments(),d.getSafetyNotes(),d.getEquipment().stream().map(RecipeEquipmentResponse::from).toList(),d.getGallery().stream().map(RecipeMediaResponse::from).toList());}}
 public record RecipeRevisionResponse(UUID id,RecipeRevisionStatus status,long baseVersion,Instant createdAt,Instant submittedAt,Instant decidedAt,String rejectionReason){public static RecipeRevisionResponse from(CultureRecipeRevision r){return r==null?null:new RecipeRevisionResponse(r.getId(),r.getStatus(),r.getBaseVersion(),r.getCreatedAt(),r.getSubmittedAt(),r.getDecidedAt(),r.getStatus()==RecipeRevisionStatus.REJECTED?r.getReviewReason():null);}}
 public record ContentResponse(UUID id,ContentType type,String slug,ContentStatus status,Visibility visibility,String primaryLanguageCode,String countryCode,String adminLevel1Id,String adminLevel2Id,String cityId,String localityId,String communityName,String createdBy,ContributorType contributorType,SourceType sourceType,VerificationStatus verificationStatus,SensitivityLevel sensitivityLevel,Instant createdAt,Instant updatedAt,Instant publishedAt,long version,ProverbDetailsResponse proverbDetails,RecipeDetailsResponse recipeDetails,RecipeRevisionResponse recipeRevision){public static ContentResponse from(CultureContent c){return from(c,null);}public static ContentResponse from(CultureContent c,CultureRecipeRevision r){return new ContentResponse(c.getId(),c.getType(),c.getSlug(),c.getStatus(),c.getVisibility(),c.getPrimaryLanguageCode(),c.getCountryCode(),c.getAdminLevel1Id(),c.getAdminLevel2Id(),c.getCityId(),c.getLocalityId(),c.getCommunityName(),c.getCreatedBy(),c.getContributorType(),c.getSourceType(),c.getVerificationStatus(),c.getSensitivityLevel(),c.getCreatedAt(),c.getUpdatedAt(),c.getPublishedAt(),c.getVersion(),ProverbDetailsResponse.from(c.getProverbDetails()),RecipeDetailsResponse.from(c.getRecipeDetails()),RecipeRevisionResponse.from(r));}}
 public record TranslationResponse(UUID id,String languageCode,String title,String summary,String body,String translatorId,TranslationStatus status,Instant createdAt){public static TranslationResponse from(CultureTranslation t){return new TranslationResponse(t.getId(),t.getLanguageCode(),t.getTitle(),t.getSummary(),t.getBody(),t.getTranslatorId(),t.getStatus(),t.getCreatedAt());}}
 public record StatusRequest(@NotNull ContentStatus status,boolean verified,String reason){}
 public record ReviewRequest(@NotNull ContentStatus decision,boolean verified,@NotBlank String reason){}
 public record LanguageResponse(String code,String name,String nativeName,List<String> countryCodes,String writingSystem,LanguageStatus status,String description,Long speakerEstimate,boolean verified){public static LanguageResponse from(Language l){return new LanguageResponse(l.getCode(),l.getName(),l.getNativeName(),l.getCountryCodes(),l.getWritingSystem(),l.getStatus(),l.getDescription(),l.getSpeakerEstimate(),l.isVerified());}}
 public record LessonSummary(UUID id,String languageCode,UUID topicId,String title,String description,int difficulty,int estimatedMinutes,LessonStatus status,int displayOrder){public static LessonSummary from(LanguageLesson l){return new LessonSummary(l.getId(),l.getLanguageCode(),l.getTopicId(),l.getTitle(),l.getDescription(),l.getDifficulty(),l.getEstimatedMinutes(),l.getStatus(),l.getDisplayOrder());}}
 public record LessonItemResponse(UUID id,String phrase,String translation,String transcription,String phonetic,UUID audioMediaId,UUID imageMediaId,String culturalContext,int difficulty,String examples,int displayOrder){public static LessonItemResponse from(LanguageLessonItem i){return new LessonItemResponse(i.getId(),i.getPhrase(),i.getTranslation(),i.getTranscription(),i.getPhonetic(),i.getAudioMediaId(),i.getImageMediaId(),i.getCulturalContext(),i.getDifficulty(),i.getExamples(),i.getDisplayOrder());}}
 public record ExerciseResponse(UUID id,ExerciseType type,String prompt,String optionsJson,int displayOrder){public static ExerciseResponse from(LanguageExercise e){return new ExerciseResponse(e.getId(),e.getType(),e.getPrompt(),e.getOptionsJson(),e.getDisplayOrder());}}
 public record LessonDetail(LessonSummary lesson,List<LessonItemResponse> items,List<ExerciseResponse> exercises){}
 public record AttemptRequest(@NotNull UUID exerciseId,String answerText,UUID mediaId){}
 public record AttemptResponse(UUID attemptId,Boolean correct,boolean manualReviewRequired){}
 public record CompleteRequest(@Min(0)@Max(100)int score,@NotBlank String idempotencyKey){}
 public record ProgressResponse(UUID id,String userId,String languageCode,UUID lessonId,Instant startedAt,Instant completedAt,Integer score,int attemptCount){public static ProgressResponse from(LanguageProgress p){return new ProgressResponse(p.getId(),p.getUserId(),p.getLanguageCode(),p.getLessonId(),p.getStartedAt(),p.getCompletedAt(),p.getScore(),p.getAttemptCount());}}
}
